mapper.select:
select b.BOOKSET_ID booksetId, b.BUSI_ID busiId, DATE_FORMAT(b.CDATE,'%Y-%m-%d') cdate, b.RECAL_TYPE recalType, b.DAILYDSC_YIELD dailydscYield , FORMAT(cast(b.DAILYDSC_YIELD as decimal(36,12)), 12) dailydscYieldFt from BOK_AMO_CONFIG b where 1=1
and b.BOOKSET_ID =#{booksetId}
and BUSI_ID = #{finprodId}
and CDATE <=STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
and CDATE >=STR_TO_DATE(#{vdateBegin},'%Y-%m-%d')
and b.RECAL_TYPE =#{recalType}

select distinct DATE_FORMAT(BOOKSET_DATE,'%Y-%m-%d')
from BOK_BOOKSET_DATE
where BOOKSET_ID=#{booksetId}
